/**
 * The culture of a company: a strip of three pictures, the heading, a few figures and the values. Axes: layout
 * (split: the pictures beside the text, stacked: the pictures under it), tone, density.
 */
import { For, type JSX } from "solid-js";
import { Box, Grid, Group, Stack, Text } from "../compose";
import { LucideIcon } from "../icons/LucideIcon";
import { MediaFrame } from "../components/media-frame";
import { SectionFrame } from "../components/section-frame";
import { cn } from "../utils";
import type { Stat } from "./stats-band.types";
import type { Feature } from "./feature-grid.types";

export type AboutCompanyProps = {
  id: string;
  title: string;
  lead?: string;
  stats: Stat[];
  values: Feature[];
  layout?: "split" | "stacked";
  tone?: "default" | "muted";
  density?: "default" | "compact";
  landmarkLabel?: string;
};

export function AboutCompany({
  id,
  title,
  lead = "",
  stats,
  values,
  layout = "split",
  tone = "default",
  density = "default",
  landmarkLabel,
}: AboutCompanyProps) {
  return (
    <SectionFrame
      id={id}
      title={title}
      lead={lead}
      tone={tone}
      density={density}
      layout={(((layout as string) === "split") ? "split" : "stack")}
      media={{ show: true, side: "start" }}
      landmarkLabel={landmarkLabel}
      aside={(
        <Box class="grid grid-cols-3 gap-4" data-slot="strip">
          <MediaFrame alt={title} ratio="3/4" />
          <MediaFrame alt={title} ratio="3/4" class="mt-8" />
          <MediaFrame alt={title} ratio="3/4" />
        </Box>
      )}
    >
      {((stats?.length ?? 0) > 0) ? (
        <Grid cols="2-4" class="gap-4" data-slot="stats">
          <For each={stats ?? []}>{(s) => (
            <Stack gap="0" data-slot="stat">
              <Text size="3xl" weight="bold">
                {s.value}
              </Text>
              <Text size="xs" class="text-muted-foreground">
                {s.label}
              </Text>
            </Stack>
          )}</For>
        </Grid>
      ) : null}
      {((values?.length ?? 0) > 0) ? (
        <Box
          class={cn("grid grid-cols-1 gap-4", (((layout as string) === "stacked") ? "md:grid-cols-3" : ""))}
          data-slot="values"
        >
          <For each={values ?? []}>{(v) => (
            <Group gap="4" align="start" class="border-t border-border pt-4" data-slot="value">
              <LucideIcon name={v.icon} size={20} />
              <Stack gap="2">
                <Text size="sm" weight="semibold">
                  {v.title}
                </Text>
                <Text size="sm" class="text-muted-foreground">
                  {v.text}
                </Text>
              </Stack>
            </Group>
          )}</For>
        </Box>
      ) : null}
    </SectionFrame>
  );
}
